input.command:
$files = git ls-files
$totalSize = 0
$totalLines = 0
$fileCount = 0
$byExt = @{}
foreach ($f in $files) {
    if (Test-Path -LiteralPath $f) {
        $size = (Get-Item -LiteralPath $f).Length
        $totalSize += $size
        $fileCount++
        $ext = [System.IO.Path]::GetExtension($f).TrimStart('.').ToLower()
        if (-not $byExt.ContainsKey($ext)) { $byExt[$ext] = @{Count=0; Size=0; Lines=0} }
        $byExt[$ext].Count++
        $byExt[$ext].Size += $size
        # Count lines for text-like files
        if ($ext -in @('ts','js','json','md','txt','yml','yaml','mjs','cjs','html','css','sh','ps1','toml','gitignore','lock','env','')) {
            try {
                $bytes = [System.IO.File]::ReadAllBytes($f)
                $text = [System.Text.Encoding]::UTF8.GetString($bytes)
                $lineCount = ($text -split "`n").Length
                $totalLines += $lineCount
                $byExt[$ext].Lines += $lineCount
            } catch {}
        }
    }
}
"=== METRICAS GLOBALES ==="
"Archivos: $fileCount"
"Total lineas: $totalLines"
"Tamano total: $([math]::Round($totalSize/1024,2)) KB ($([math]::Round($totalSize/1MB,2)) MB)"
""
"=== POR EXTENSION ==="
"{0,-12} {1,8} {2,12} {3,10}" -f "Extension","Archivos","Lineas","Tamano(KB)"
"{0,-12} {1,8} {2,12} {3,10}" -f "---------","--------","------","----------"
$byExt.GetEnumerator() | Sort-Object { $_.Value.Size } -Descending | ForEach-Object {
    "{0,-12} {1,8} {2,12} {3,10}" -f $_.Key, $_.Value.Count, $_.Value.Lines, [math]::Round($_.Value.Size/1024,2)
}

