$root = (Get-Location).Path
$outDir = "C:\Users\JOSEES~1\AppData\Local\Temp\opencode"
if (-not (Test-Path -LiteralPath $outDir)) { New-Item -ItemType Directory -Path $outDir | Out-Null }
$zipPath = Join-Path $outDir "klia-token-optimizer-repo.zip"

# Excluir directorios (cualquier segmento del path) y patrones
$excludeDirs = @('.git','node_modules','dist','.vitest','.opencode','.kilo','.serena','.tmp-test-router','.router-history','.planning','tests\.tmp-asterisk')
$excludeDirSet = @('.git','node_modules','dist','.vitest','.opencode','.kilo','.serena','.tmp-test-router','.router-history','.planning')

# Patrones de archivo a excluir (regex sobre el nombre)
$excludeFilePatterns = @(
    '\.log$','\.log\.json$',
    '\.env$','\.env\.local$','.*\.env$',
    '\.bak$','\.backup\..*$',
    'tokens\.txt$',
    'Thumbs\.db$','\.DS_Store$',
    'repomix-output\.xml$',
    '\.git\.zip$',
    'package-lock\.json$'
)

$allFiles = Get-ChildItem -LiteralPath $root -Recurse -File -Force
$kept = New-Object System.Collections.Generic.List[object]
$skipped = 0
foreach ($f in $allFiles) {
    $rel = $f.FullName.Substring($root.Length+1)
    $parts = $rel -split '[\\/]'
    $skip = $false
    foreach ($p in $parts) {
        if ($excludeDirSet -contains $p) { $skip = $true; break }
        # excluir tests/.tmp-* por patron gitignore
        if ($p -like '.tmp-*') { $skip = $true; break }
    }
    if (-not $skip) {
        foreach ($pat in $excludeFilePatterns) {
            if ($f.Name -match $pat) { $skip = $true; break }
        }
    }
    if (-not $skip) { $kept.Add($f) } else { $skipped++ }
}

"Archivos a empaquetar: $($kept.Count)"
"Archivos excluidos: $skipped"
"Tamano total: $([math]::Round(($kept | Measure-Object -Property Length -Sum).Sum / 1MB, 2)) MB"

# Guardar la lista para el siguiente paso
$kept | Select-Object FullName, Length | Export-Csv -LiteralPath "$outDir\filelist.csv" -NoTypeInformation
"Lista guardada en: $outDir\filelist.csv"

