$root = (Get-Location).Path
$csv = Import-Csv -LiteralPath "C:\Users\JOSEES~1\AppData\Local\Temp\opencode\filelist.csv"
$byExt = @{}
$totalSize = 0
$totalLines = 0
$totalFiles = 0
foreach ($row in $csv) {
    $f = $row.FullName
    if (-not (Test-Path -LiteralPath $f)) { continue }
    $size = [long]$row.Length
    $totalSize += $size
    $totalFiles++
    $ext = [System.IO.Path]::GetExtension($f).TrimStart('.').ToLower()
    if (-not $ext) { $ext = '(sin ext)' }
    if (-not $byExt.ContainsKey($ext)) { $byExt[$ext] = @{Count=0; Size=0; Lines=0} }
