    $textExt = @('ts','js','mjs','cjs','cts','json','md','txt','yml','yaml','html','css','sh','ps1','toml','gitignore','lock','env','csv','xml','svg','map','cjs','rs','go','py','rb','java','c','cpp','h','hpp','cs')
    if ($textExt -contains $ext -or $ext -eq '(sin ext)') {
        try {
            $bytes = [System.IO.File]::ReadAllBytes($f)
