                $lineCount = ($text -split "`n").Length
                if ($text.Length -gt 0 -and -not $text.EndsWith("`n")) { $lineCount++ }
                # Restar 1 si el texto termina con newline (split genera un elemento vacio final)
                if ($text.Length -gt 0 -and $text.EndsWith("`n")) { $lineCount-- }
                $byExt[$ext].Lines += $lineCount
                $totalLines += $lineCount
            }
        } catch {}
    }
}

